  public function verificaPrilegio($currentForm)
  { 
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
		return 0;
	}else{
		return 1;
	}	 
  }
  
  public function executeIndex()
  {
    return $this->forward('imagenes_documentacion', 'list');
  }

  public function executeList()
  { 
  	$dirForm  = ParametroPeer::retrieveByPk(44);
  	$this->url = $dirForm->getValortexto();
  	/*********************************************************************************************************/ 		$c = new Criteria();
  	$parametros = '';  	
  	$c->add(ImagenesDocumentacionPeer::DOCUMENTACION_ID,$this->getRequestParameter('documentacion_id'));
    /*********************************************************************************************************/
	$pager = new sfPropelPager('ImagenesDocumentacion', 10);
	$pager->setCriteria($c);        
	$pager->setPage($this->getRequestParameter('page', 1));
	$pager->init();
	$this->pager = $pager;
	$this->parametros = $parametros;
	$this->documentacion = 	$this->getRequestParameter('documentacion_id');
	$titulo = DocumentacionPeer::retrieveByPk($this->getRequestParameter('documentacion_id'));	    
	/**********************************************************************************************************/
	$tipo_documentacion = $titulo->getTipodocumentacionId();
