		case 2:
		      $modulo = 'CATALOGOS';		      
		break;
		case 3:
		      $modulo = 'INFORMES_TECNICOS';		      
		break;
		case 4:
		      $modulo = 'LIBROS';		      
		break;
		case 5:
		      $modulo = 'PLANOS';		      
		break;
		case 6:
		      $modulo = 'PUBLICACIONES_SERIADAS';		      
		break;
		case 7:
		      $modulo = 'REGISTROS';		      
		break;
		case 8:
		      $modulo = 'MEDIOS_AUDIOVISUALES';		      
		break;
		case 9:
		      $modulo = 'MEDIOS_MAGNETICOS';		      
		break;
	}
	$currentFormCrear    = 'ADJUNTAR_IMAGENES_'.$modulo;
 	$currentFormEditar   = 'EDITAR_ADJUNTOS_'.$modulo;
	$this->permisoCrear  = $this->verificaPrilegio($currentFormCrear);
