  public function executeShow()
  {
    $this->imagenes_documentacion = ImagenesDocumentacionPeer::retrieveByPk($this->getRequestParameter('imagenesdocumentacion_id'));
    $this->forward404Unless($this->imagenes_documentacion);
  }

  public function executeCreate()
  {
  	$this->documentacionId = $this->getRequestParameter('documentacion_id');
  	$this->vincular        = $this->getRequestParameter('vincular');
  	$this->documentacion_tecnica = null;
    $this->imagenes_documentacion = new ImagenesDocumentacion();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $imagenes_documentacion = ImagenesDocumentacionPeer::retrieveByPk($this->getRequestParameter('imagenesdocumentacion_id'));
    
	$this->vincular = $imagenes_documentacion->getVinculada();
    $this->documentacionId = $imagenes_documentacion->getDocumentacionId();
    if($imagenes_documentacion->getVinculada()){
		$this->documentacion_tecnica = DocumentacionPeer::retrieveByPK($imagenes_documentacion->getRuta());
	}
    $this->imagenes_documentacion = $imagenes_documentacion;
    $this->forward404Unless($this->imagenes_documentacion);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('imagenesdocumentacion_id'))
    {
      $imagenes_documentacion = new ImagenesDocumentacion();
      $old_files = false;
      $txt_oldfiles = "";
    }
    else
    {
      $imagenes_documentacion = ImagenesDocumentacionPeer::retrieveByPk($this->getRequestParameter('imagenesdocumentacion_id'));
      $old_files = true;
      $txt_oldfiles = $imagenes_documentacion->getRuta();
      $this->forward404Unless($imagenes_documentacion);
    }
    //*********************************************************************************************
    $imagenes_documentacion->setDocumentacionId($this->getRequestParameter('documentacion_id'));    
    $imagenes_documentacion->setDescripcion($this->getRequestParameter('descripcion'));
    $imagenes_documentacion->setFolios($this->getRequestParameter('folios'));
    //**************************************************************************************************
    $str_files = trim($this->getRequestParameter('ruta'));
    $imagenes_documentacion->setRuta($this->resolveUrlAttachment($str_files,$old_files,$txt_oldfiles));
    //**************************************************************************************************	
	if($this->getRequestParameter('titulo')){		
		$imagenes_documentacion->setRuta($this->getRequestParameter('vincular_id'));
		$imagenes_documentacion->setVinculada(true);
	}
    //**************************************************************************************************
    $imagenes_documentacion->save();
    return $this->redirect($this->getRequest()->getScriptName().'/imagenes_documentacion/list?documentacion_id='.$imagenes_documentacion->getDocumentacionId());
  }    
  
